   351→/*******************************************************************************
   352→* ������   : PYTHON5000USB_WaitPllLock
   353→* ��  ��  : �ȴ� PLL ��������ѯ�Ĵ��� 24 bit0����� 20 �Σ�ÿ�� 200ms��
   354→* ��  ��  : pSensorObj - ����������
   355→* ��  ��  : ��
   356→* ����ֵ   : 0,�����ɹ�����0ʧ��
   357→*******************************************************************************/
   358→static int PYTHON5000USB_WaitPllLock(PYTHON5000USB_SensorObj *pSensorObj)
   359→{
   360→    int pll_lock_flag = 1;
   361→    int lock_cnt = 20;
   362→    uint16_t rdata = 0;
   363→
   364→    while ((pll_lock_flag) && (lock_cnt > 0)) {
   365→        PAL_usleep(200000);
   366→        PYTHON5000USB_spiRead(pSensorObj, PLL_LOCK_REG, &rdata);
   367→        rdata = rdata & PLL_LOCK_BIT;
   368→        LOG_INFO("reg24 data= 0x%x\n", rdata);
   369→        if (rdata == 0x1) {
   370→            pll_lock_flag = 0;
   371→        } else {
   372→            pll_lock_flag = 1;
   373→        }
   374→        lock_cnt--;
   375→        if ((lock_cnt == 0) && (pll_lock_flag)) {
   376→            LOG_INFO("Sensor_PLL has not been locked!\n");
   377→        } else if (!pll_lock_flag) {
   378→            LOG_INFO("Sensor_PLL has been locked!, lock_cnt = %d\n", lock_cnt);
   379→        }
   380→    }
   381→
   382→    return pll_lock_flag ? -1 : 0;
   383→}
