  1189→	else if ((aGainStag1 == 0x1) && (aGainStag2 == 0x1))
  1190→		* pAnaGain = 4;
  1191→	else if ((aGainStag1 == 0x1) && (aGainStag2 == 0x6))
  1192→		* pAnaGain = 5.33;
  1193→	else if ((aGainStag1 == 0x1) && (aGainStag2 == 0x2))
