  1481→		T2 = (height*(2592 - width)) / 576;
  1482→		if (T1 < 0)	T1 = 0;
  1483→		if (T2 < 0)	T2 = 0;
  1484→		Troi = 16653.639 - T1 - T2;
  1485→	}
  1486→	else	//reg193=0xFF00
  1487→	{
  1488→		T1 = (2048 - height)*8.083;
  1489→		T2 = (height*(2592 - width)) / 576;
  1490→		if (T1 < 0)	T1 = 0;
  1491→		if (T2 < 0)	T2 = 0;
  1492→		Troi = 20157.639 - T1 - T2;
  1493→	}
  1494→
  1495→	expTimeSet = (uint32_t)(expTimeSet / 16) * 16;
  1496→	
  1497→	if (expTimeSet > Troi)
  1498→		framePeriod = PYTHON5000USB_FOT + expTimeSet + 50;
  1499→	else
  1500→		framePeriod = Troi;
  1501→	
  1502→	if(framePeriod < expTimeSet + 200)
  1503→	{
  1504→		framePeriod = expTimeSet + 200;
  1505→	}
  1506→		
  1507→	maxFrameRate = 1000000.0 / framePeriod;
  1508→
  1509→	return maxFrameRate;
  1510→}
